+}
+
+function buildBoundary(paths) {
+  return {
+    consumes_semantic_kg_layers_only: true,
+    promotion_gate_path: paths.promotionGateIn,
+    prerequisite_graph_path: paths.prerequisiteGraphIn,
+    misconception_layer_path: paths.misconceptionLayerIn,
+    mastery_signal_candidates_are_not_mastery_truth: true,
