+    no_external_llm_vlm_api_calls: true,
+    no_remote_supabase_mutation: true,
+    no_frontend_ui: true,
+    no_production_rag_reindex: true,
+  };
+}
+
+function buildContract({ generatedAt, paths, source, summary }) {
+  return {
+    schema_version: 'semantic_kg_mastery_signal_candidate_contract.v1',
