+    generated_by: SCRIPT_NAME,
+    issue: ISSUE,
+    parent_issue: PARENT_ISSUE,
+    depends_on_issues: DEPENDS_ON_ISSUES,
+    subject_code: SUBJECT_CODE,
+    objective:
+      'Define MasterySignalCandidate contract and safety boundary without producing mastery truth.',
+    boundary: buildBoundary(paths),
+    source_contract: source,
+    output_artifacts: {
+      contract: paths.contractOut,
+      candidates: paths.candidatesOut,
+      safety_fixtures: paths.safetyFixturesOut,
+      safety_validator: paths.validatorOut,
+      readback: paths.readbackOut,
+    },
+    mastery_signal_candidate_schema: {
+      object_type: 'MasterySignalCandidate',
+      required_fields: [
+        'mastery_signal_candidate_id',
+        'signal_state',
+        'target_refs',
+        'source_semantic_assertion_refs',
+        'evidence_posture',
+        'permitted_downstream_uses',
+        'forbidden_downstream_uses',
+        'runtime_mastery_update_allowed',
+      ],
+      allowed_signal_states: ALLOWED_SIGNAL_STATES,
+      target_refs: {
+        concept_ref: 'Concept link allowed only as semantic target context.',
+        skill_ref: 'Skill link allowed only as semantic target context.',
+        misconception_ref: 'Misconception link allowed only as review context.',
+        attempt_error_signal_ref: 'AttemptErrorSignal link allowed only as evidence posture context.',
+      },
+      evidence_posture: {
+        semantic_only: 'May be candidate_signal, review_required, suppressed, or blocked_quarantined.',
+        reviewed_semantic: 'May be provisional_signal but still cannot update mastery.',
+        real_attempt_evidence_required: true,
+      },
+    },
+    safety_policy: {
+      candidate_signal: {
+        runtime_mastery_update_allowed: false,
+        future_learner_model_consumption_allowed: true,
+      },
+      provisional_signal: {
+        runtime_mastery_update_allowed: false,
+        future_learner_model_consumption_allowed: true,
+      },
+      review_required: {
+        runtime_mastery_update_allowed: false,
+        future_learner_model_consumption_allowed: false,
+      },
+      suppressed: {
+        runtime_mastery_update_allowed: false,
+        future_learner_model_consumption_allowed: false,
+      },
+      blocked_quarantined: {
+        runtime_mastery_update_allowed: false,
+        future_learner_model_consumption_allowed: false,
+        terminal_categorical_exclusion: true,
+      },
+      no_accepted_mastery_update_state_in_semantic_kg: true,
+      confidence_score_is_not_mastery_truth: true,
+    },
+    downstream_handoff: {
+      future_chain: 'learner-model-hvy',
+      permitted_uses: [
+        'future candidate feature input with real attempt evidence',
+        'review queue prioritization',
+        'non-authoritative diagnostic safety context',
+      ],
+      forbidden_uses: [
+        'runtime mastery score update',
+        'personalized learner model mutation',
+        'student-facing deterministic diagnosis',
+        'accepted mastery truth assertion',
+      ],
+    },
+    summary,
+    content_hash: {
+      algorithm: 'sha256',
+      value: sha256Value({
+        issue: ISSUE,
+        allowed_signal_states: ALLOWED_SIGNAL_STATES,
+        summary,
+      }),
+    },
+  };
+}
+
+function buildRealCandidates({ generatedAt, paths }) {
+  return {
+    schema_version: 'semantic_kg_mastery_signal_candidates.v1',
+    generated_at: generatedAt,
+    generated_by: SCRIPT_NAME,
+    issue: ISSUE,
+    parent_issue: PARENT_ISSUE,
+    source_contract_path: paths.contractOut,
+    summary: {
+      candidate_count: 0,
+      candidate_signal_count: 0,
+      provisional_signal_count: 0,
