+      source_status: 'review_required',
+      source_layer: 'review_required',
+      target_ref_kind: 'Misconception',
+      semantic_signal_strength: 'weak',
+      has_real_attempt_evidence: false,
+      requests_mastery_update: false,
+      expected_signal_state: 'review_required',
+    },
+    {
+      fixture_id: 'fixture-blocked-quarantined-terminal',
+      description: 'blocked_quarantined remains terminal regardless of confidence.',
+      source_status: 'blocked_quarantined',
+      source_layer: 'blocked_quarantined',
+      target_ref_kind: 'AttemptErrorSignal',
+      confidence: { confidence_band: 'high', confidence_score: 1 },
+      blocked_quarantined: true,
+      has_real_attempt_evidence: false,
+      requests_mastery_update: true,
+      expected_signal_state: 'blocked_quarantined',
+    },
+  ];
+}
+
+function buildSafetyFixtures({ generatedAt, paths }) {
+  const fixture_results = defaultSafetyFixtures().map(routeMasterySignalFixture);
+  return {
+    schema_version: 'semantic_kg_mastery_signal_safety_fixtures.v1',
+    generated_at: generatedAt,
+    generated_by: SCRIPT_NAME,
+    issue: ISSUE,
+    parent_issue: PARENT_ISSUE,
+    source_contract_path: paths.contractOut,
+    summary: {
+      fixture_count: fixture_results.length,
+      fixture_pass_count: fixture_results.filter((fixture) => fixture.pass).length,
+      fixture_fail_count: fixture_results.filter((fixture) => !fixture.pass).length,
+      runtime_mastery_update_count:
+        fixture_results.filter((fixture) => fixture.runtime_mastery_update_allowed).length,
+      external_model_call_count: 0,
+    },
+    fixture_results,
+    state_counts: countBy(fixture_results, 'actual_signal_state'),
+    content_hash: {
+      algorithm: 'sha256',
+      value: sha256Value({ issue: ISSUE, fixture_results }),
+    },
+  };
+}
+
+function buildSummary({ inputs, safetyFixtures }) {
+  return {
+    represented_row_count: inputs.promotionGate?.summary?.represented_row_count ?? 0,
+    source_semantic_assertion_count:
+      inputs.promotionGate?.summary?.classified_assertion_count ?? 0,
+    source_layer_entry_count: inputs.promotionGate?.summary?.layer_entry_count ?? 0,
+    source_prerequisite_candidate_count:
+      inputs.prerequisiteGraph?.summary?.candidate_count ?? 0,
+    source_misconception_attempt_error_candidate_count:
+      inputs.misconceptionLayer?.summary?.candidate_count ?? 0,
+    mastery_signal_candidate_count: 0,
+    candidate_signal_count: 0,
+    provisional_signal_count: 0,
+    review_required_count: 0,
+    suppressed_count: 0,
+    blocked_quarantined_count: 0,
+    runtime_mastery_update_count: 0,
+    accepted_mastery_update_count: 0,
+    safety_fixture_count: safetyFixtures.summary.fixture_count,
+    safety_fixture_pass_count: safetyFixtures.summary.fixture_pass_count,
+    safety_fixture_fail_count: safetyFixtures.summary.fixture_fail_count,
+    external_model_call_count: 0,
+  };
+}
+
+function passCheck(id, evidence = {}) {
+  return { id, status: 'pass', evidence };
+}
+
+function failCheck(id, reason, evidence = {}) {
+  return { id, status: 'fail', reason, evidence };
+}
+
+function inputDiagnosticsCritical(inputDiagnostics) {
+  return (Array.isArray(inputDiagnostics) ? inputDiagnostics : [])
+    .filter((diagnostic) => diagnostic?.severity === 'critical');
+}
+
+function validateMasterySignalContract({
+  contract,
+  candidatesLayer,
+  safetyFixtures,
+  inputs,
+  inputDiagnostics,
+}) {
+  const criticalDiagnostics = inputDiagnosticsCritical(inputDiagnostics);
+  const validatorStatuses = [
+    inputs.promotionValidator?.summary?.validation_status ??
+      inputs.promotionValidator?.validator_status ??
+      null,
+    inputs.prerequisiteValidator?.summary?.validation_status ??
+      inputs.prerequisiteValidator?.validator_status ??
+      null,
+    inputs.misconceptionValidator?.summary?.validation_status ??
+      inputs.misconceptionValidator?.validator_status ??
+      null,
+  ];
+  const candidateStates = candidatesLayer.candidates.map((candidate) => candidate.signal_state);
+  const serialized = JSON.stringify({ contract, candidatesLayer, safetyFixtures });
+  const checks = [
+    criticalDiagnostics.length === 0
+      ? passCheck('upstream_inputs_loaded', { critical_diagnostic_count: 0 })
+      : failCheck('upstream_inputs_loaded', 'critical_input_diagnostics_present', {
+        critical_diagnostics: criticalDiagnostics,
+      }),
+    validatorStatuses.every((status) => status === 'pass')
+      ? passCheck('upstream_validators_passed', { validator_statuses: validatorStatuses })
+      : failCheck('upstream_validators_passed', 'upstream_validator_not_pass', {
+        validator_statuses: validatorStatuses,
+      }),
+    ALLOWED_SIGNAL_STATES.every((state) => (
+      contract.mastery_signal_candidate_schema.allowed_signal_states.includes(state)
+    ))
+      ? passCheck('signal_state_enum_declared', { allowed_signal_states: ALLOWED_SIGNAL_STATES })
+      : failCheck('signal_state_enum_declared', 'missing_required_signal_state'),
+    candidateStates.every((state) => ALLOWED_SIGNAL_STATES.includes(state))
+      ? passCheck('candidate_signal_states_valid', { candidate_count: candidateStates.length })
+      : failCheck('candidate_signal_states_valid', 'unknown_candidate_signal_state'),
+    candidatesLayer.summary.runtime_mastery_update_count === 0 &&
+      candidatesLayer.summary.accepted_mastery_update_count === 0 &&
+      !serialized.match(/"runtime_mastery_update_allowed"\s*:\s*true/i)
+      ? passCheck('no_runtime_mastery_update_produced', {})
+      : failCheck('no_runtime_mastery_update_produced', 'runtime_mastery_update_emitted'),
+    safetyFixtures.summary.fixture_fail_count === 0 &&
+      safetyFixtures.summary.runtime_mastery_update_count === 0
+      ? passCheck('weak_semantic_evidence_cannot_update_mastery', {
+        fixture_count: safetyFixtures.summary.fixture_count,
+      })
+      : failCheck('weak_semantic_evidence_cannot_update_mastery', 'fixture_allowed_update'),
+    safetyFixtures.fixture_results.some((fixture) => (
+      fixture.fixture_id === 'fixture-blocked-quarantined-terminal' &&
+      fixture.actual_signal_state === 'blocked_quarantined' &&
+      fixture.runtime_mastery_update_allowed === false
+    ))
+      ? passCheck('blocked_quarantined_terminal', {})
+      : failCheck('blocked_quarantined_terminal', 'blocked_fixture_not_terminal'),
+    contract.downstream_handoff.forbidden_uses.includes('runtime mastery score update') &&
+      contract.downstream_handoff.forbidden_uses.includes('personalized learner model mutation') &&
+      contract.downstream_handoff.forbidden_uses.includes('accepted mastery truth assertion')
+      ? passCheck('downstream_forbidden_uses_declared', {})
+      : failCheck('downstream_forbidden_uses_declared', 'missing_forbidden_use'),
+    !serialized.match(/"(student_id|learner_id)"\s*:/i)
+      ? passCheck('no_real_student_identifiers', {})
+      : failCheck('no_real_student_identifiers', 'student_identifier_serialized'),
+    contract.boundary.no_external_model_calls === true &&
+      contract.summary.external_model_call_count === 0 &&
+      !serialized.match(/external_model_call_count"\s*:\s*[1-9]/)
+      ? passCheck('no_external_model_calls', { external_model_call_count: 0 })
+      : failCheck('no_external_model_calls', 'external_model_call_recorded'),
+    !serialized.match(/api[_-]?key|secret|access[_-]?token|refresh[_-]?token|bearer|private[_-]?key/i)
+      ? passCheck('no_credential_like_serialization', {})
+      : failCheck('no_credential_like_serialization', 'credential_like_field_serialized'),
+  ].sort((left, right) => compareByteOrder(left.id, right.id));
+  const checkFailCount = checks.filter((check) => check.status === 'fail').length;
+  const validationStatus = checkFailCount === 0 ? 'pass' : 'fail';
+  return {
+    schema_version: 'semantic_kg_mastery_signal_safety_validator.v1',
+    generated_at: contract.generated_at,
+    generated_by: SCRIPT_NAME,
+    issue: ISSUE,
+    parent_issue: PARENT_ISSUE,
+    contract_path: contract.output_artifacts.contract,
+    candidates_path: contract.output_artifacts.candidates,
+    safety_fixtures_path: contract.output_artifacts.safety_fixtures,
+    validator_status: validationStatus,
+    summary: {
+      validation_status: validationStatus,
+      check_count: checks.length,
+      check_pass_count: checks.length - checkFailCount,
+      check_fail_count: checkFailCount,
+      mastery_signal_candidate_count: contract.summary.mastery_signal_candidate_count,
+      candidate_signal_count: contract.summary.candidate_signal_count,
+      provisional_signal_count: contract.summary.provisional_signal_count,
+      review_required_count: contract.summary.review_required_count,
+      suppressed_count: contract.summary.suppressed_count,
+      blocked_quarantined_count: contract.summary.blocked_quarantined_count,
+      runtime_mastery_update_count: contract.summary.runtime_mastery_update_count,
+      accepted_mastery_update_count: contract.summary.accepted_mastery_update_count,
+      safety_fixture_count: safetyFixtures.summary.fixture_count,
+      safety_fixture_pass_count: safetyFixtures.summary.fixture_pass_count,
+      safety_fixture_fail_count: safetyFixtures.summary.fixture_fail_count,
+      external_model_call_count: 0,
+    },
+    checks,
+    input_diagnostics: Array.isArray(inputDiagnostics) ? inputDiagnostics : [],
+  };
+}
+
